-- Tags: no-fasttest
-- no-fasttest: requires the ORC input format, which is not built in fasttest.

SET allow_experimental_variant_type = 1;

-- ORC uniontype<struct<a:int,b:string>, string>, rows: struct{10,'x'}, string 'hello', struct{20,'y'}.
-- The struct branch is matched against an explicit Variant alternative by field name, just like the
-- non-union ORC struct path, so a target tuple may project (drop) and reorder the ORC struct fields.

-- Baseline: the inferred schema keeps all fields in the ORC order.
SELECT toTypeName(u) FROM format(ORC, unhex('')) LIMIT 1;

-- Projection: keep only the `b` field of the struct branch.
SELECT u FROM format(ORC, $$u Variant(Tuple(b String), String)$$, unhex('')) ORDER BY toString(u);

-- Reorder: swap the fields of the struct branch to (b, a).
SELECT u FROM format(ORC, $$u Variant(Tuple(b String, a Int32), String)$$, unhex('')) ORDER BY toString(u);
